// Builds the website's generated files from the real product code, so the free
// health check on the site runs exactly the same rules as the product.
//   npm run build:site   → writes site/assets/health-core.js and site/assets/data.js
// test/site.test.ts fails if these files are out of date.
import { readFileSync, writeFileSync } from 'node:fs';
import { stripTypeScriptTypes } from 'node:module';
import { fileURLToPath } from 'node:url';
import { agentSummary } from '../src/agents/index.ts';
import { RULES } from '../src/checks/health-check.ts';

const ROOT = new URL('../', import.meta.url);
const BANNER = '// GENERATED by scripts/build-site.ts from the Hyniqe Growth source. Do not edit by hand.\n';

export function buildSiteFiles(): Record<string, string> {
  const core = readFileSync(new URL('src/checks/health-core.ts', ROOT), 'utf8');
  const js = stripTypeScriptTypes(core, { mode: 'strip' })
    .split('\n')
    // Strip mode leaves blanks where the types were; tidy them so the file reads well.
    .map((l) => l.replace(/(\S) {2,}(?=[;,)])/g, '$1').replace(/(\S) {2,}(?=[={])/g, '$1 ').replace(/\s+$/, ''))
    .join('\n')
    .replace(/\n{3,}/g, '\n\n');
  const demo = (f: string) => readFileSync(new URL(`data/demo/sites/${f}`, ROOT), 'utf8');
  const data = {
    RULES,
    AGENTS: agentSummary(),
    DEMO_SITES: {
      cafe: { label: 'A café with a weak website', url: 'https://chaiandcrumb.example', html: demo('chai-and-crumb.html') },
      saas: { label: 'A SaaS company with a strong website', url: 'https://ledgerly.example', html: demo('ledgerly.html') },
    },
  };
  return {
    'site/assets/health-core.js': BANNER + js.trim() + '\n',
    'site/assets/data.js': BANNER + Object.entries(data).map(([k, v]) => `export const ${k} = ${JSON.stringify(v, null, 2)};`).join('\n\n') + '\n',
  };
}

if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) {
  for (const [path, content] of Object.entries(buildSiteFiles())) {
    writeFileSync(new URL(path, ROOT), content);
    console.log(`wrote ${path}`);
  }
}
